using System.Xml.Linq;

[Form]
public class TFMDocumentQueue extends FormRun
{
    Range                   statusRangeString;

    QueryBuildRange         userIdRange;
    QueryBuildRange         documentTypeRange;
    QueryBuildRange         statusRange;
    boolean                 devMode;
    boolean                 showAll;
    boolean                 newDocument;
    boolean                 readyForProcessing;
    boolean                 processing;
    boolean                 completed;
    boolean                 error;

    TFMDocumentTypeId       documentType;
    UserId                  userId;

    #DEFINE.CurrentVersion(2)
    #LOCALMACRO.CurrentList
        showAll,
        userId,
        documentType,
        newDocument,
        readyForProcessing,
        processing,
        completed,
        error
    #ENDMACRO

}

// AOSRunMode::Client
public void close()
{
    xSysLastValue::saveLast(this);

    super();

}

void enableButtons()
{

    TFMDocumentQueue_ds.allowEdit(TFMDocumentQueue.Status == TFMDocumentQueueStatus::NewDocument || TFMDocumentQueue.Status == TFMDocumentQueueStatus::Error || TFMDocumentQueue.Status == TFMDocumentQueueStatus::ReadyForProcessing || devMode);

    ResetStatus.enabled(TFMDocumentQueue.Status == TFMDocumentQueueStatus::Processing);

    OpenReference.enabled(TFMDocumentQueue.RefRecId);
    FindCode.visible(FindCode.enabled(devMode));
    ResetData.visible(ResetData.enabled(devMode));
}

void enableControls()
{
    // Enable or disable filters based on the value of the show all control
    ctrlUserId.enabled(!showAll);
    ctrlDocumentType.enabled(!showAll);
    ctrlNewDocument.enabled(!showAll);
    ctrlReadyForProcessing.enabled(!showAll);
    ctrlProcessing.enabled(!showAll);
    ctrlCompleted.enabled(!showAll);
    ctrlError.enabled(!showAll);
}

public void init()
{
    super();

    xSysLastValue::getLast(this);

    element.setControls();
    element.enableControls();
    devMode = TFMParameters::find().DeveloperMode;
}

void initParmDefault()
{

    showAll = true;
}

// AOSRunMode::Client
dataAreaId lastValueDataAreaId()
{
    return curext();
}

// AOSRunMode::Client
identifiername lastValueDesignName()
{
    return '';
}

// AOSRunMode::Client
identifiername lastValueElementName()
{
    return this.name();
}

