UtilElementType lastValueType()
{
    return UtilElementType::Form;
}

// AOSRunMode::Client
userId lastValueUserId()
{
    return curuserid();
}

public container pack()
{
    return [#CurrentVersion,
        ctrlShowAll.value(),
        ctrlUserId.text(),
        ctrlDocumentType.text(),
        ctrlNewDocument.value(),
        ctrlReadyForProcessing.value(),
        ctrlProcessing.value(),
        ctrlCompleted.value(),
        ctrlError.value()
        ];

}

void setControls()
{
    ctrlShowAll.value(showAll);
    ctrlUserId.text(UserId);
    ctrlDocumentType.text(documentType);
    ctrlNewDocument.value(newDocument);
    ctrlReadyForProcessing.value(readyForProcessing);
    ctrlProcessing.value(processing);
    ctrlCompleted.value(completed);
    ctrlError.value(error);
}

void setStatusRangeString()
{
    statusRangeString = strfmt(identifierstr('%1, %2, %3, %4, %5'),
                        (ctrlNewDocument.value()            ? queryValue(TFMDocumentQueueStatus::NewDocument)   : SysQuery::valueNot(TFMDocumentQueueStatus::NewDocument)),
                        (ctrlReadyForProcessing.value()     ? queryValue(TFMDocumentQueueStatus::ReadyForProcessing)   : SysQuery::valueNot(TFMDocumentQueueStatus::ReadyForProcessing)),
                        (ctrlProcessing.value()             ? queryValue(TFMDocumentQueueStatus::Processing)    : SysQuery::valueNot(TFMDocumentQueueStatus::Processing)),
                        (ctrlCompleted.value()              ? queryValue(TFMDocumentQueueStatus::Completed)     : SysQuery::valueNot(TFMDocumentQueueStatus::Completed)),
                        (ctrlError.value()                  ? queryValue(TFMDocumentQueueStatus::Error)         : SysQuery::valueNot(TFMDocumentQueueStatus::Error)));
}

/// <summary>
/// Initialize the XML viewer for the Request
/// </summary>
/// <remarks>
/// Called from TabPage pageActivated method
/// </remarks>
public void showRequestXML()
{
    str xml;
    //str tempFile;
    str xmlError;
    System.Exception ex;
    System.Exception iex;

    xml = TFMDocumentQueue.RequestXML();
    RequestXmlViewer.visible(false);
    XmlParseError.visible(false);
    try
    {

        RequestXmlViewer.parmFormatAsXml('Yes');
        RequestXmlViewer.parmHtml(TFMFormXMLFormatter::htmlColorXML(xml));

        RequestXmlViewer.visible(true);
    }
    catch(Exception::CLRError)
    {
        XmlParseError.visible(true);
        ex = CLRInterop::getLastException();
        iex = ex.get_InnerException();
        if (iex)
        {
            ex = iex;
        }
        xmlError = ex.ToString();
        XmlParseError.Text( xmlError );

    }		    

}

/// <summary>
/// Initialize the XML viewer for the Answer
/// </summary>
/// <remarks>
/// Called from TabPage pageActivated method
/// </remarks>
public void showResponseXML()
{
    str xml;
    xml = TFMDocumentQueue.AnswerXML();
    ResponseXmlViewer.parmFormatAsXml('Yes');
    ResponseXmlViewer.parmHtml(TFMFormXMLFormatter::htmlColorXML(xml));
    ResponseXmlViewer.visible(true);
}

/// <summary>
/// Initialize the XML viewer for the Result
/// </summary>
/// <remarks>
/// Called from TabPage pageActivated method
/// </remarks>
public void showResultXML()
{
    str xml;        
    #Xml

    xml = TFMDocumentQueue.ResultXML();    
    ResultXmlViewer.parmFormatAsXml('Yes');
    ResultXmlViewer.parmHtml(TFMFormXMLFormatter::htmlColorXML(xml));
    ResultXmlViewer.visible(true);
}

public boolean unpack(container packedClass)
{
    Integer version     = conpeek(packedClass,1);

    switch (version)
    {
        case #CurrentVersion :
            [version,#CurrentList] = packedClass;
            break;
        default :
            return false;
    }

    return true;
}

public void executeQuery()
{
    if (showAll)
    {
        statusRange.value(sysQuery::valueUnlimited());
        userIdRange.value(sysQuery::valueUnlimited());
        documentTypeRange.value(sysQuery::valueUnlimited());
    }
    else
    {
        element.setStatusRangeString();
        statusRange.value(statusRangeString);
        userIdRange.value(userId);
        documentTypeRange.value(documentType);
    }

    super();
}

public void init()
{
    super();

    TFMDocumentQueue_ds.query().dataSourceTable(tableNum(TFMDocumentQueue)).addSortField(FieldNum(TFMDocumentQueue, createdDateTime), SortOrder::Descending);

    statusRange             = TFMDocumentQueue_ds.query().dataSourceTable(tableNum(TFMDocumentQueue)).addRange(fieldnum(TFMDocumentQueue,Status));
    userIdRange             = TFMDocumentQueue_ds.query().dataSourceTable(tableNum(TFMDocumentQueue)).addRange(fieldnum(TFMDocumentQueue,UserId));
    documentTypeRange       = TFMDocumentQueue_ds.query().dataSourceTable(tableNum(TFMDocumentQueue)).addRange(fieldnum(TFMDocumentQueue,DocumentType));
}

public int active()
{
    int ret;

    ret = super();
    element.enableButtons();

    return ret;
}

        public void displayOption(Common _record, FormRowDisplayOption _options)
        {
            TFMDocumentQueue queue = _record;
            if (queue.Status == TFMDocumentQueueStatus::Error)
            {
				_options.backColor(WinAPI::RGB2int(255, 230, 230));
            }
            super(_record, _options);
        }

boolean modified()
{
    boolean ret;

    ret = super();

    // Find value of the show all control
    showAll = this.value();

    // Enable controls
    element.enableControls();

    // Run query with the new filter options
    TFMDocumentQueue_ds.executeQuery();

    return ret;
}

