/// <summary>
///
/// </summary>
public void clicked()
{
    super();
    System.IO.MemoryStream stream = new System.IO.MemoryStream();
    System.IO.StreamWriter writer = new System.IO.StreamWriter(stream,System.Text.Encoding::GetEncoding(1252));
    writer.Write('<?xml version="1.0" encoding="utf-8"?>'+TFMDocumentQueue.RequestXML());
    writer.Flush();
    stream.Position = 0;

    str fileName = TFMDocumentQueue.DocumentType + (TFMDocumentQueue.ContentSubject ? '('+ TFMDocumentQueue.ContentSubject + ')' : '') + ' Request ' +TFMDocumentQueue.UserId + '@' + TFMDeviceTable::FindOrCreateDevice(TFMDocumentQueue.DeviceId).Name + ' ' +strFmt('%1',TFMDocumentQueue.CreatedDateTime);
    str contentType = 'application/text';
    str fileExtension = '.xml';//SRSPrintDestinationSettings::findFileNameType(SRSReportFileFormat::PDF, SRSImageFileFormat::BMP);
    FileUploadTemporaryStorageStrategy fileUploadStrategy = new FileUploadTemporaryStorageStrategy();
    FileUploadTemporaryStorageResult fileUploadResult = fileUploadStrategy.uploadFile(stream, fileName + fileExtension, contentType , fileExtension);

    Browser br = new Browser();
    br.navigate(fileUploadResult.getDownloadUrl(),false, false);
}

