/// <summary>
///
/// </summary>
public void clicked()
{
    #AOT            
    TFMDocumentHandler  documentHandler = TFMDocumentTypeProvider::handler(TFMDocumentQueue.DocumentType);
    DictMethod          method;
    str                 methodString;
    super();
    documentHandler.setRequestXml(TFMXMLDeserializer::getXmlDocument(TFMDocumentQueue.RequestXML()));
    documentHandler = documentHandler.subHandler();
    method = documentHandler.parmMethod();
    if (Method != null)            
    {
        methodString = #AOTDelimiter + method.name();                
    }
    Info(#ClassesPath + #AOTDelimiter +classId2Name(classIdGet(documentHandler)) + methodString);
}

public void clicked()
{
    Map                         models = TFMExportSetup::getTables();
    MapEnumerator				mEnum = models.getEnumerator();
    Map							tables;
    MapEnumerator				tEnum;
    TableName					tName;
    Common						common;
    super();

    if (Box::okCancel("@TFM:Areyousureyouwanttodeleteallthes",DialogButton::Cancel) != DialogButton::Ok)
    {
        return;
    }

    while (Menum.moveNext())
    {
        tables = mEnum.currentValue();
        tEnum = tables.getEnumerator();
        while (tEnum.moveNext())
        {
            tName = tEnum.currentKey();
            common = new SysDictTable(TableName2id(tName)).makeRecord();
            common.skipDataMethods(true);
            delete_from common;
        }
    }

}
